~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .substituir(/\s+/g, ' ')
    .trim();
}

/**
 * Pesquisa de alta precisão e mecanismo de consulta semântica
 */
exportar função assíncrona searchSentences(
  consulta: string,
  filtros: SearchFilterOptions = {}
): Promessa<{resultados: SentenceItem[]; total:número; semanticMatches?: SemanticExplanationMatch[] }> {
  const all = aguarda loadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery? normalizedQuery.split(' ').filter(Boolean) : [];

  const{
    cefr = 'todos',
    seção = 'todos',
    categoria = 'todos',
    subcategoria = 'todos',
    gramática = 'todos',
    formalidade = 'todos',
    limite = 50,
    deslocamento = 0,
  } = filtros;

  // Filtrar passagem
  deixe filtrado = all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) retorna falso;
    if (seção !== 'todos' && s.seção !==seção) retorna falso;
    if (categoria! == 'todos' && s.categoria! == categoria) retornar falso;
    if (subcategoria! == 'todos' && s.subcategoria! == subcategoria) retornar falso;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) return false;
    if (formality !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) return false;
    retornar verdadeiro;
  });

  if (!normalizedQuery) {
    const total = comprimento filtrado;
    const paginado = filtrado. fatia(deslocamento, deslocamento + limite);
    return {resultados: paginado, total};
  }

  // Algoritmo de pontuação
  interfaceScoredItem {
    item:SentençaItem;
    pontuação:número;
    aspecto: SemanticExplanationMatch['matchedAspect'];
  }

  const pontuado: ScoredItem[] = [];

  for (const s de filtrado) {
    deixe pontuação = 0;
    deixe matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'inglês';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.propósito);

    //Correspondência exata da frase completa
    if (normEn === normalizedQuery) {
      pontuação += 100;
      matchedAspect = 'inglês';
    } else if (normEg === normalizedQuery) {
      pontuação += 95;
      matchedAspect = 'árabe-por exemplo';
    } else if (normFusha === normalizedQuery) {
      pontuação += 90;
      matchedAspect = 'árabe-fusha';
    }

    //Substring contém
    if (normEn.includes(normalizedQuery)) {
      pontuação += 50;
      matchedAspect = 'inglês';
    } else if (normEg.includes(normalizedQuery)) {
      pontuação += 45;
      matchedAspect = 'árabe-por exemplo';
    } else if (normFusha.includes(normalizedQuery)) {
      pontuação += 40;
      matchedAspect = 'árabe-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      pontuação += 35;
      matchedAspect = 'gramática';
    } else if (normPurpose.includes(normalizedQuery)) {
      pontuação += 30;
      matchedAspect = 'conceito';
    }

    //correspondência de token
    deixe tokenMatches = 0;
    for (token const de queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    pontuação += tokenMatches;

    if (pontuação > 0) {
      score.push({ item: s, pontuação, aspecto: matchedAspect });
    }
  }

  pontuado.sort((a, b) => b.pontuação - a.pontuação);

  // A explicação semântica corresponde aos itens principais
  const semanticMatches: SemanticExplanationMatch[] = score.slice(0, 5).map(s => {
    deixe nuance = '';
    if (s.item.grammar.toLowerCase().includes('passado contínuo')) {
      nuance = 'O pretérito contínuo mostra que um evento estava em andamento em um ponto específico no passado.';
    } else if (s.item.grammar.toLowerCase().includes('presente perfeito contínuo')) {
      nuance = 'O presente perfeito contínuo enfatiza o tempo do passado e continua até o momento da fala.';
    } else if (s.item.grammar.toLowerCase().includes('futuro perfeito')) {
      nuance = 'O futuro perfeito expressa que um evento será concluído antes de um momento específico no futuro.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'A forma de solicitação indireta é o ápice da etiqueta diplomática na comunicação em inglês.';
    }
    retornar {
      frase: s.item,
      pontuação de similaridade: Math.min (100, s.score),
      nuanceExplicaçãoAr: nuance,
      aspecto correspondente: s.aspecto,
    };
  });

  const total = pontuado. comprimento;
  const paginado = pontuado.slice(deslocamento, deslocamento + limite).map(s => s.item);

  retornar {
    resultados: paginado,
    total,
    semânticaCorrespondências,
  };
}

